<script setup lang="ts">
import { computed,ref } from 'vue'
import ExploreFrame from './ExploreFrame.vue'
import { useExperience } from './use-experience'
import { careEco,ecoAnimalTeams,ecoLocations,ecoBins,ecoLitter,sortLitter } from './eco-guardian'
const props=defineProps<{storageKey?:string}>()
const {save,frame,feedback,resetOpen,act,undo,requestReset,reset,hint}=useExperience(props,'eco-guardian')
const round=computed(()=>save.value.round),picked=ref(-1),clean=computed(()=>round.value.cleaned.length===round.value.litter.length)
const location=computed(()=>ecoLocations[round.value.location || 0]),animals=computed(()=>ecoAnimalTeams[round.value.location || 0])
const binCounts=computed(()=>ecoBins.map((_,bin)=>round.value.cleaned.filter(index=>ecoLitter[round.value.litter[index]].bin===bin).length))
const rules=['用模拟夹子选择场景里的垃圾，再点对应收集箱；电脑也可以拖到收集箱。','分错时会解释原因，垃圾会留在原处，可以换一个箱子再试。','场景清理干净后，和救护站一起帮助三只动物；现实中危险废物交给大人按当地规则处理。']
function select(index:number){picked.value=index;feedback.value='已用夹子选中'+ecoLitter[round.value.litter[index]].name+'，再选择收集箱。'}
function bin(index:number,item=picked.value){if(item<0){feedback.value='先从场景选一个要收集的物品。';return}const result=act(()=>sortLitter(round.value,item,index));if(result){feedback.value=result.text;if(result.passed)picked.value=-1}}
function drag(event:DragEvent,index:number){select(index);event.dataTransfer?.setData('text/plain',String(index))}
function drop(event:DragEvent,index:number){const value=event.dataTransfer?.getData('text/plain') || '';if(!/^\d+$/.test(value))return;bin(index,Number(value))}
</script>
<template>
  <ExploreFrame v-bind="frame" :progress="`清理 ${round.cleaned.length} / ${round.litter.length} 件 · 动物 ${round.cared.length} / 3`" :rules="rules" @difficulty="requestReset" @undo="undo();picked=-1" @restart="requestReset()" @reset="reset();picked=-1" @cancel="resetOpen=false" @hint="hint(picked>=0?ecoLitter[round.litter[picked]].name+'应放进'+ecoBins[ecoLitter[round.litter[picked]].bin].name+'。':clean?location+'干净了，点击下方三个动物帮助按钮。':'先选一个物品。干净的纸、瓶子可以回收；果皮属于厨余，用过的纸巾属于其他垃圾。')">
    <div class="eco-beach" :class="[{clean},`eco-location-${round.location || 0}`]" :aria-label="location+'清理区'"><span class="eco-sun">☀</span><div class="eco-wave"></div><span class="eco-beach-caption">{{ clean?'干净的'+location+'，欢迎小伙伴回来。':'把垃圾收走，给动物留下干净的家。' }}</span><div class="eco-litter-grid"><button v-for="(item,index) in round.litter" :key="index" :data-litter="index" :class="{removed:round.cleaned.includes(index),selected:picked===index}" :disabled="round.cleaned.includes(index) || round.finished" :aria-label="`收集 ${index+1} ${ecoLitter[item].name}`" :draggable="!round.cleaned.includes(index)" @dragstart="drag($event,index)" @click="select(index)"><span>{{ ecoLitter[item].icon }}</span><small>{{ ecoLitter[item].name }}</small></button></div><div class="eco-beach-animals"><span v-for="animal in animals" :key="animal.name">{{ animal.icon }}</span></div></div>
    <p class="explore-caption">{{ picked>=0?'夹子已选中：'+ecoLitter[round.litter[picked]].name:'先选物品，再选收集箱。' }}</p>
    <div class="eco-bins"><button v-for="(container,index) in ecoBins" :key="container.name" :data-bin="index" :style="{borderColor:container.color}" :disabled="round.finished" @click="bin(index)" @dragover.prevent @drop.prevent="drop($event,index)"><span>{{ container.icon }}</span><strong>{{ container.name }}</strong><small>已收集 {{ binCounts[index] }} 件</small></button></div>
    <h2 class="explore-subheading">{{ location }} · 和救护站一起帮助动物</h2><div class="explore-cards eco-care"><button v-for="(animal,index) in animals" :key="animal.name" class="explore-card" :disabled="!clean || round.cared.includes(index) || round.finished" :aria-label="animal.action" @click="act(()=>careEco(round,index));feedback=animal.name+'得到帮助啦，'+location+'又恢复了生机。'"><span>{{ animal.icon }}</span>{{ animal.name }}<small>{{ round.cared.includes(index)?'已帮助 ✓':clean?animal.action:'先清理'+location }}</small></button></div>
  </ExploreFrame>
</template>
<style scoped>
.eco-location-1{background:linear-gradient(#e4f0f7 0%,#e4f0f7 25%,#c5dab4 25%,#d5e4c2 100%)}.eco-location-2{background:linear-gradient(#cadfc5 0%,#b1cfac 25%,#e1d4b7 25%,#c7dcb7 100%)}.eco-location-1 .eco-wave,.eco-location-2 .eco-wave{border-color:#79996c;top:23%}

.eco-beach{position:relative;border:1px solid #d5e0d2;border-radius:18px;background:linear-gradient(#e4f0f7 0%,#e4f0f7 24%,#bad6dc 24%,#bad6dc 39%,#eee0bb 39%);overflow:hidden;padding:115px 17px 65px;min-height:340px}.eco-sun{position:absolute;right:24px;top:14px;color:#d5b565;font-size:34px}.eco-wave{position:absolute;left:-10%;right:-10%;top:34%;height:20px;border-radius:50%;border-top:8px solid #edf5eee6}.eco-beach-caption{position:absolute;top:30px;left:20px;max-width:70%;font-size:12px;color:#7397a3;line-height:1.8}.eco-litter-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.eco-litter-grid button{display:flex;flex-direction:column;align-items:center;gap:7px;border:1px solid #ddcda4;border-radius:12px;background:#fff7dd80;padding:10px 3px;min-width:0;color:#a29271;transition:opacity .3s}.eco-litter-grid button.selected{border-color:#b99854;box-shadow:0 0 0 2px #d9b973}.eco-litter-grid button.removed{visibility:hidden;opacity:0}.eco-litter-grid button>span{font-size:28px}.eco-litter-grid small{font-size:9px}.eco-beach-animals{display:flex;justify-content:space-around;position:absolute;left:10%;right:10%;bottom:14px;font-size:29px;opacity:.6}.eco-beach.clean .eco-beach-animals{opacity:1}.eco-bins{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.eco-bins button{display:flex;flex-direction:column;align-items:center;gap:13px;padding:20px 4px;border:2px solid #c6d6bc;border-bottom-width:6px;border-radius:13px;background:#fff;color:#7c8d73}.eco-bins button>span{font-size:29px}.eco-bins strong{font-size:11px;font-weight:650}.eco-care small{text-align:center;line-height:1.7}@media(max-width:560px){.eco-beach{padding:110px 11px 65px}.eco-beach-caption{font-size:11px;left:15px}.eco-litter-grid{gap:7px}.eco-litter-grid small{font-size:8px}.eco-litter-grid button>span{font-size:25px}.eco-bins{gap:7px}.eco-bins button{padding:17px 3px}.eco-bins strong{font-size:9px}.eco-bins button>span{font-size:25px}.eco-care small{font-size:9px}}@media(prefers-reduced-motion:reduce){.eco-litter-grid button{transition:none}}
</style>
